<?php
/**
 * Prom.ua marketplace categories (the list behind <portal_category_id>).
 *
 * Prom publishes its categories with their ids as an XLS file
 * (https://my.prom.ua/cabinet/export_categories/xls). The plugin ships a compact
 * copy in data/prom-categories.tsv ("id<TAB>path" per line), regenerated by
 * bin/update-prom-categories.py, so the admin picks a category by name instead
 * of looking the number up by hand.
 *
 * @package Factorial2000_Catalog_Sync
 */

namespace F2000CS;

defined( 'ABSPATH' ) || exit;

/**
 * Lookup and search in the bundled category list.
 */
class Prom_Categories {

	/**
	 * Loaded list: id => path.
	 *
	 * @var array<string,string>|null
	 */
	private static $list = null;

	/**
	 * Path of the data file.
	 *
	 * @return string
	 */
	public static function file(): string {
		/**
		 * Filters the file with the Prom category list ("id<TAB>path" per line).
		 *
		 * @param string $file Absolute path.
		 */
		return (string) apply_filters( 'f2000cs_prom_categories_file', __DIR__ . '/data/prom-categories.tsv' );
	}

	/**
	 * All categories: id => "Level 1 > Level 2 > …".
	 *
	 * @return array<string,string>
	 */
	public static function all(): array {
		if ( null !== self::$list ) {
			return self::$list;
		}

		self::$list = array();
		$file       = self::file();

		if ( ! is_readable( $file ) ) {
			return self::$list;
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_file -- Bundled read-only data file.
		foreach ( (array) file( $file, FILE_IGNORE_NEW_LINES | FILE_SKIP_EMPTY_LINES ) as $line ) {
			if ( '' === $line || '#' === $line[0] ) {
				continue;
			}

			$tab = strpos( $line, "\t" );

			if ( false === $tab ) {
				continue;
			}

			$id   = trim( substr( $line, 0, $tab ) );
			$path = trim( substr( $line, $tab + 1 ) );

			if ( ctype_digit( $id ) && '' !== $path ) {
				self::$list[ $id ] = $path;
			}
		}

		return self::$list;
	}

	/**
	 * Forget the loaded list (tests, or after the file filter changed).
	 *
	 * @return void
	 */
	public static function reset(): void {
		self::$list = null;
	}

	/**
	 * Path of a category, or '' when the id is unknown.
	 *
	 * @param string|int $id Category id.
	 * @return string
	 */
	public static function path( $id ): string {
		$id = trim( (string) $id );

		return self::all()[ $id ] ?? '';
	}

	/**
	 * Whether the id is in the list.
	 *
	 * @param string|int $id Category id.
	 * @return bool
	 */
	public static function exists( $id ): bool {
		return '' !== self::path( $id );
	}

	/**
	 * Find categories by words of their path or by the beginning of the id.
	 *
	 * Every word must occur in the path (any order, case-insensitive). Categories
	 * whose own (last) name contains the words come first, then shorter paths.
	 *
	 * @param string $query Search text.
	 * @param int    $limit Maximum results.
	 * @return array<int, array{id:string,path:string}>
	 */
	public static function search( string $query, int $limit = 20 ): array {
		$query = Marketplace_Text::lower( Marketplace_Text::clean( $query ) );

		if ( '' === $query || $limit < 1 ) {
			return array();
		}

		$hits = array();

		if ( ctype_digit( $query ) ) {
			foreach ( self::all() as $id => $path ) {
				if ( 0 === strpos( (string) $id, $query ) ) {
					$hits[] = array( (string) $id === $query ? 0 : 1, strlen( (string) $id ), (string) $id, $path );
				}
			}
		} else {
			$words = array_filter( (array) preg_split( '/[\s,>]+/u', $query ) );

			foreach ( self::all() as $id => $path ) {
				$lower = Marketplace_Text::lower( $path );

				foreach ( $words as $word ) {
					if ( false === mb_strpos( $lower, $word ) ) {
						continue 2;
					}
				}

				$pos  = mb_strrpos( $lower, '>' );
				$leaf = false === $pos ? $lower : mb_substr( $lower, $pos + 1 );
				$rank = 1;

				foreach ( $words as $word ) {
					if ( false !== mb_strpos( $leaf, $word ) ) {
						$rank = 0;
						break;
					}
				}

				$hits[] = array( $rank, mb_strlen( $path ), (string) $id, $path );
			}
		}

		usort(
			$hits,
			static function ( $a, $b ) {
				return array( $a[0], $a[1], $a[3] ) <=> array( $b[0], $b[1], $b[3] );
			}
		);

		$out = array();

		foreach ( array_slice( $hits, 0, $limit ) as $hit ) {
			$out[] = array(
				'id'   => $hit[2],
				'path' => $hit[3],
			);
		}

		return $out;
	}

	/**
	 * Digits only (what Prom expects in <portal_category_id>).
	 *
	 * @param mixed $value Raw value.
	 * @return string
	 */
	public static function sanitize_id( $value ): string {
		return (string) preg_replace( '/[^0-9]/', '', (string) $value );
	}
}
